const assetPreviewMemory = {};

const reminderMessages = [
  'Catat sesuai barang yang kamu ambil.',
  'Kejujuran tumbuh dari pilihan sederhana.',
  'Bayar dengan benar, jaga kepercayaan bersama.',
  'Ambil secukupnya, bertanggung jawablah.'
];
const activeRoute = () => route.split('?')[0].replace(/\/$/,'') || 'home';
const dashboardSessionKey = role => `kantin-kejujuran:dashboard-unlocked:${role}`;
function roleForRoute(){
  const current=activeRoute();
  if(current==='admin'||current.startsWith('admin/'))return 'admin';
  if(current==='seller'||current.startsWith('seller/'))return 'seller';
  return '';
}
function roleUnlocked(role){
  if(!['admin','seller'].includes(role))return false;
  try{const expires=Number(sessionStorage.getItem(dashboardSessionKey(role))||0);return Number.isFinite(expires)&&expires>Date.now();}catch{return false;}
}
function unlockRole(role){
  if(!['admin','seller'].includes(role))return false;
  try{sessionStorage.setItem(dashboardSessionKey(role),String(Date.now()+4*60*60*1000));return roleUnlocked(role);}catch{return false;}
}
function lockRole(role){
  if(!['admin','seller'].includes(role))return false;
  try{sessionStorage.removeItem(dashboardSessionKey(role));return true;}catch{return false;}
}
function stableSettingValue(value){
  if(Array.isArray(value))return `[${value.map(stableSettingValue).join(',')}]`;
  if(value&&typeof value==='object')return `{${Object.keys(value).sort().map(key=>`${JSON.stringify(key)}:${stableSettingValue(value[key])}`).join(',')}}`;
  return JSON.stringify(value);
}
const currentSettings = () => {
  const published=publicData?.settings||{};
  const draft=Store.get('settingsDraft',null);
  if(draft&&typeof draft==='object'&&stableSettingValue(draft)===stableSettingValue(published)){
    Store.remove('settingsDraft');
    return {...published};
  }
  return {...published,...(draft||{})};
};
const featureEnabled = (key, fallback=true) => { const s=currentSettings(); return s[key]===undefined?fallback:s[key]!==false; };
const whatsappDigits = value => String(value||'').replace(/\D/g,'');
const whatsappConfigured = s => { const n=whatsappDigits(s?.whatsappAdminNumber); return n.length>=8&&n.length<=15; };
const publishedProducts = () => Array.isArray(publicData?.products) ? publicData.products : fallbackProducts;
const draftProducts = () => getDraftProducts(publishedProducts());
const draftCategories = () => getDraftCategories(publicData.categories);
const productImage = p => assetSrc(p?.image);
const qrisConfigured = settings => Boolean(settings.qrisEnabled && settings.qrisImage && /^(\.\/)?assets\/[a-z0-9_./-]+$/i.test(String(settings.qrisImage).trim()) && !String(settings.qrisImage).includes('..'));
function assetPathValid(value){const path=String(value||'').trim();return !path||( /^(?:\.\/)?assets\/[a-z0-9_./-]+$/i.test(path)&&!path.includes('..')&&!path.includes('//'));}
function assetSrc(value,fallback='assets/images/products/placeholder-product.svg'){
  const path=String(value||'').trim().replace(/^\.\/+/, '');
  const previews=Store.get('assetPreviews',{});
  const preview=assetPreviewMemory[path]||previews[path]||assetPreviewMemory[String(value||'')]||previews[String(value||'')];
  if(typeof preview==='string'&&/^data:image\/(?:png|jpeg|webp);base64,/i.test(preview))return preview;
  if(/^assets\/[a-z0-9_./-]+$/i.test(path)&&!path.includes('..')&&!path.includes('//'))return `./${path}`;
  const safeFallback=String(fallback||'assets/images/products/placeholder-product.svg').replace(/^\.\/+/, '');
  return /^assets\/[a-z0-9_./-]+$/i.test(safeFallback)&&!safeFallback.includes('..')?`./${safeFallback}`:'./assets/images/products/placeholder-product.svg';
}
const statusBadge = (p) => `<span class="pill ${stockClass(p)}"><span class="status-dot"></span>${escapeHtml(stockLabel(p))}</span>`;
const stockStatus = p => Number(p.stock)===0 ? 'Habis' : Number(p.stock)<=Number(p.lowStockThreshold??5) ? 'Stok terbatas' : 'Tersedia';

function navLink(path, label, iconName, exact=false) {
  const isActive = exact ? activeRoute()===path : activeRoute()===path || activeRoute().startsWith(`${path}/`);
  return `<a class="nav-link ${isActive?'active':''}" href="#/${path}" ${isActive?'aria-current="page"':''}>${icon(iconName,16)}<span>${label}</span></a>`;
}
