  const mobileItems=[['home','Beranda','home'],['catalog','Belanja','bag'],...(featureEnabled('enableTransparency')?[['transparency','Transparansi','shield']]:[]),['guide','Panduan','book'],...(featureEnabled('enableCart')?[['cart','Keranjang','cart']]:[])];
