function filteredProducts(){
  let products=activeProducts(publishedProducts());
  if(catalogState.search.trim()) { const q=catalogState.search.trim().toLocaleLowerCase('id-ID'); products=products.filter(p=>`${p.name} ${p.description||''} ${categoryName(p.categoryId,publicData.categories)}`.toLocaleLowerCase('id-ID').includes(q)); }
  if(catalogState.category!=='all') products=products.filter(p=>p.categoryId===catalogState.category);
  if(catalogState.availability==='available') products=products.filter(p=>Number(p.stock)>0);
  if(catalogState.availability==='out') products=products.filter(p=>Number(p.stock)===0);
  if(catalogState.sort==='name') products.sort((a,b)=>a.name.localeCompare(b.name,'id'));
  if(catalogState.sort==='price-asc') products.sort((a,b)=>a.price-b.price);
  if(catalogState.sort==='price-desc') products.sort((a,b)=>b.price-a.price);
  if(catalogState.sort==='stock') products.sort((a,b)=>b.stock-a.stock);
  return products;
}
function renderCatalogGrid(){
  const products=filteredProducts(); const grid=$('#catalog-grid'); if(!grid)return;
  grid.innerHTML=products.length?products.map(p=>productCard(p)).join(''):`<div class="empty-state" style="grid-column:1/-1"><div class="empty-icon">${icon('search',24)}</div><h3>Produk tidak ditemukan</h3><p>Coba ubah kata pencarian atau filter kategori yang dipilih.</p><button class="button button-secondary" data-action="reset-catalog">Atur ulang filter</button></div>`;
  const count=$('#catalog-result-count');if(count)count.textContent=`${products.length} produk ditemukan`;
}
