  $('#dialog-root').innerHTML=`<div class="dialog-backdrop" data-action="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="product-dialog-title"><div class="dialog-head"><div><span class="eyebrow"><span class="eyebrow-dot"></span>Draft produk lokal</span><h3 id="product-dialog-title" style="margin-top:7px">${product?'Edit produk':'Tambah produk'}</h3></div><button class="dialog-close" data-action="dialog-close" aria-label="Tutup">${icon('close',18)}</button></div><form data-form="product" class="page-stack" style="gap:14px"><div class="form-grid"><div class="field full"><label for="product-name">Nama produk *</label><input class="input" id="product-name" name="name" value="${escapeHtml(p.name)}" minlength="2" maxlength="90" required></div><div class="field full"><label for="product-description">Deskripsi</label><textarea class="textarea" id="product-description" name="description" maxlength="500">${escapeHtml(p.description||'')}</textarea></div><div class="field"><label for="product-price">Harga (rupiah) *</label><input class="input" id="product-price" name="price" type="number" min="0" max="100000000" step="1" value="${escapeHtml(p.price)}" required></div><div class="field"><label for="product-unit">Satuan *</label><input class="input" id="product-unit" name="unit" value="${escapeHtml(p.unit||'buah')}" maxlength="24" required></div><div class="field"><label for="product-category">Kategori *</label><select class="select" id="product-category" name="categoryId" required>${cats.map(c=>`<option value="${escapeHtml(c.id)}" ${c.id===p.categoryId?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field"><label for="product-stock">Stok katalog *</label><input class="input" id="product-stock" name="stock" type="number" min="0" max="1000000" step="1" value="${escapeHtml(p.stock)}" required></div><div class="field"><label for="product-threshold">Ambang stok rendah</label><input class="input" id="product-threshold" name="lowStockThreshold" type="number" min="0" step="1" value="${escapeHtml(p.lowStockThreshold??5)}"></div><div class="field full"><label for="product-image">Path gambar lokal</label><input class="input" id="product-image" name="image" value="${escapeHtml(p.image||'assets/images/products/placeholder-product.svg')}" maxlength="200"><span class="field-hint">Path file yang akan diunggah ke repository.</span><label for="product-image-upload" class="file-drop" style="margin-top:8px">Unggah foto produk (PNG/JPG/WebP)<input id="product-image-upload" type="file" accept="image/png,image/jpeg,image/webp" data-asset-upload data-target-field="product-image" data-asset-folder="assets/images/products" data-asset-name="product-${slugify(p.name||'baru')}"><span class="field-hint">File terunduh otomatis; unggah ke folder assets/images/products/ di GitHub.</span></label></div><div class="field full"><label class="checkbox-row"><input type="checkbox" name="isActive" ${p.isActive!==false?'checked':''}><span>Produk aktif pada katalog draft</span></label></div></div><div class="notice info">${icon('info',16)}<div>Perubahan disimpan otomatis pada browser ini dan terlihat pada halaman pembeli di browser yang sama. Perangkat lain hanya melihat data publik yang sudah diterbitkan.</div></div><div class="button-row"><button type="submit" class="button button-primary">${icon('check',15)} Simpan draft</button><button type="button" class="button button-secondary" data-action="dialog-close">Batal</button></div><div id="product-form-errors" class="field-error" role="alert"></div></form></section></div>`;
  $('#product-name')?.focus();
