      const all=allKnownTransactions();const stamp=new Date().toISOString();
      const yes=await confirmDialog('Reset pendapatan kumulatif?',`Nilai pendapatan yang ditampilkan akan dihitung ulang mulai ${dateTime(stamp)}. Riwayat transaksi tidak dihapus, tetapi catatan transaksi lama tetap ada. Cadangan data transaksi akan diunduh terlebih dahulu.`, 'Reset pendapatan', true);
      if(yes){downloadJSON({exportedAt:stamp,reason:'backup-before-revenue-reset',transactions:all},`cadangan-transaksi-sebelum-reset-${stamp.slice(0,10)}.json`);if(!Store.set('revenueResetAt',stamp))throw new Error('Reset gagal disimpan. Penyimpanan browser mungkin penuh.');showToast('Pendapatan kumulatif direset; riwayat transaksi tetap dipertahankan.','success');render();}
