      const products=draftProducts();if(!products.length){showToast('Tidak ada produk pada draft.');return;}
      const yes=await confirmDialog('Set semua stok ke 0?',`Semua ${products.length} produk di draft akan diset ke stok 0. Cadangan katalog saat ini akan diunduh terlebih dahulu. Riwayat mutasi tidak dihapus. Perubahan baru terlihat publik setelah ekspor dan push.`, 'Set stok ke 0', true);
      if(yes){const stamp=new Date().toISOString();downloadJSON(products,`cadangan-katalog-sebelum-reset-stok-${stamp.slice(0,10)}.json`);const next=products.map(p=>({...p,stock:0,updatedAt:stamp}));saveDraftProducts(next);const moves=Store.get('stockMovements',[]);saveOrThrow('stockMovements',[...next.map(p=>({id:uid('STK'),productId:p.id,type:'penyesuaian',quantity:0,note:'Reset stok oleh admin ke 0',createdAt:stamp,source:'admin-stock-reset'})),...moves]);showToast('Semua stok draft diubah menjadi 0. Ekspor katalog dan push untuk menerbitkan.','success');render();}
