      showImportPreview('transactions',list,{title:`${list.length} transaksi ditemukan`,description:'Data yang sudah ada tidak akan dihitung ganda. Impor akan menyimpan transaksi baru di perangkat ini.',details:[`${list.length-duplicates} ID diperkirakan baru`,`${duplicates} ID sudah ada dan akan dilewati`].concat(list.length? [`Contoh: ${list.slice(0,3).map(t=>t.id).join(', ')}`]:[])});
